      assert.ok(!f.writes.some(write => write.name === 'arm'), `${decision} must never arm auto-merge`);
      assert.equal(f.writes.some(write => write.name === 'disarm'), armed);
      assert.ok(!f.writes.some(write => write.name === 'review'));
    }
  }
});

